     4→
     5→export function useTrackView(entityType: string, entityId: string) {
     6→  const tracked = useRef(false);
     7→
     8→  useEffect(() => {
     9→    if (tracked.current || !entityId) return;
    10→    tracked.current = true;
    11→
    12→    fetch('/api/track/view', {
    13→      method: 'POST',
    14→      headers: { 'Content-Type': 'application/json' },
    15→      body: JSON.stringify({ entityType, entityId }),
    16→    }).catch(() => {});
    17→  }, [entityType, entityId]);
    18→}
