     1→import { prisma } from '@tpmjs/db';
     2→import { COLLECTION_LIMITS, CreateCollectionSchema } from '@tpmjs/types/collection';
     3→import { type NextRequest, NextResponse } from 'next/server';
     4→import { logActivity } from '~/lib/activity';
     5→import { authenticateRequest } from '~/lib/api-keys/middleware';
     6→
     7→export const runtime = 'nodejs';
     8→export const dynamic = 'force-dynamic';
     9→export const maxDuration = 60;
    10→
    11→const API_VERSION = '1.0.0';
    12→
    13→/**
    14→ * Generate a URL-friendly slug from a name
    15→ */
    16→function slugify(name: string): string {
    17→  return name
    18→    .toLowerCase()
    19→    .trim()
    20→    .replace(/[^\w\s-]/g, '') // Remove special chars
    21→    .replace(/\s+/g, '-') // Replace spaces with hyphens
    22→    .replace(/-+/g, '-') // Remove consecutive hyphens
    23→    .replace(/^-+|-+$/g, '') // Trim hyphens
    24→    .slice(0, 50);
    25→}
    26→
    27→/**
    28→ * Generate a unique slug for a collection within a user's scope
    29→ */
    30→async function generateUniqueSlug(userId: string, baseName: string): Promise<string> {
    31→  let slug = slugify(baseName);
    32→  if (!slug) slug = 'collection';
    33→
    34→  // Check if slug exists for this user
    35→  const existing = await prisma.collection.findFirst({
    36→    where: { userId, slug },
    37→    select: { id: true },
    38→  });
    39→
    40→  if (!existing) return slug;
    41→
    42→  // Append numbers until unique
    43→  let counter = 1;
    44→  while (counter < 1000) {
    45→    const candidate = `${slug.slice(0, 46)}-${counter}`;
    46→    const exists = await prisma.collection.findFirst({
    47→      where: { userId, slug: candidate },
    48→      select: { id: true },
    49→    });
    50→    if (!exists) return candidate;
    51→    counter++;
    52→  }
    53→
    54→  // Fallback: use random suffix
    55→  return `${slug.slice(0, 42)}-${Date.now().toString(36)}`;
    56→}
    57→
    58→/**
    59→ * Standard API response structure
    60→ */
    61→interface ApiResponse<T = unknown> {
    62→  success: boolean;
    63→  data?: T;
    64→  error?: {
    65→    code: string;
    66→    message: string;
    67→    details?: Record<string, unknown>;
    68→  };
    69→  meta: {
    70→    version: string;
    71→    timestamp: string;
    72→    requestId?: string;
    73→  };
    74→  pagination?: {
    75→    limit: number;
    76→    offset: number;
    77→    count: number;
    78→    hasMore: boolean;
    79→  };
    80→}
    81→
    82→/**
    83→ * GET /api/collections
    84→ * List all collections for the authenticated user
    85→ */
    86→export async function GET(request: NextRequest): Promise<NextResponse<ApiResponse>> {
    87→  const requestId = crypto.randomUUID();
    88→
    89→  try {
    90→    // Check authentication
    91→    const authResult = await authenticateRequest();
    92→
    93→    if (!authResult.authenticated || !authResult.userId) {
    94→      return NextResponse.json(
    95→        {
    96→          success: false,
    97→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
    98→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
    99→        },
   100→        { status: 401 }
   101→      );
   102→    }
   103→
   104→    // Parse pagination and search params
   105→    const searchParams = request.nextUrl.searchParams;
   106→    const limit = Math.min(Math.max(Number.parseInt(searchParams.get('limit') || '20', 10), 1), 50);
   107→    const offset = Math.max(Number.parseInt(searchParams.get('offset') || '0', 10), 0);
   108→    const search = searchParams.get('search')?.trim();
   109→
   110→    // Fetch collections with tool count
   111→    const collections = await prisma.collection.findMany({
   112→      where: {
   113→        userId: authResult.userId,
   114→        ...(search && {
   115→          OR: [
   116→            { name: { contains: search, mode: 'insensitive' } },
   117→            { description: { contains: search, mode: 'insensitive' } },
   118→          ],
   119→        }),
   120→      },
   121→      include: {
   122→        _count: { select: { tools: true } },
   123→      },
   124→      orderBy: { createdAt: 'desc' },
   125→      take: limit + 1,
   126→      skip: offset,
   127→    });
   128→
   129→    const hasMore = collections.length > limit;
   130→    const data = hasMore ? collections.slice(0, limit) : collections;
   131→
   132→    return NextResponse.json({
   133→      success: true,
   134→      data: data.map((c) => ({
   135→        id: c.id,
   136→        name: c.name,
   137→        slug: c.slug,
   138→        description: c.description,
   139→        isPublic: c.isPublic,
   140→        toolCount: c._count.tools,
   141→        createdAt: c.createdAt,
   142→        updatedAt: c.updatedAt,
   143→      })),
   144→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   145→      pagination: { limit, offset, count: data.length, hasMore },
   146→    });
   147→  } catch (error) {
   148→    console.error('[API Error] GET /api/collections:', error);
   149→    return NextResponse.json(
   150→      {
   151→        success: false,
   152→        error: { code: 'INTERNAL_ERROR', message: 'Failed to fetch collections' },
   153→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   154→      },
   155→      { status: 500 }
   156→    );
   157→  }
   158→}
