   160→/**
   161→ * POST /api/collections
   162→ * Create a new collection
   163→ */
   164→export async function POST(request: NextRequest): Promise<NextResponse<ApiResponse>> {
   165→  const requestId = crypto.randomUUID();
   166→
   167→  try {
   168→    // Check authentication
   169→    const authResult = await authenticateRequest();
   170→
   171→    if (!authResult.authenticated || !authResult.userId) {
   172→      return NextResponse.json(
   173→        {
   174→          success: false,
   175→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
   176→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   177→        },
   178→        { status: 401 }
   179→      );
   180→    }
   181→    const userId = authResult.userId;
   182→
   183→    // Parse and validate request body
   184→    const body = await request.json();
   185→    const parseResult = CreateCollectionSchema.safeParse(body);
   186→
   187→    if (!parseResult.success) {
   188→      return NextResponse.json(
   189→        {
   190→          success: false,
   191→          error: {
   192→            code: 'VALIDATION_ERROR',
   193→            message: 'Invalid request body',
   194→            details: { errors: parseResult.error.flatten().fieldErrors },
   195→          },
   196→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   197→        },
   198→        { status: 400 }
   199→      );
   200→    }
   201→
   202→    const { name, description, isPublic } = parseResult.data;
   203→
   204→    // Check collection limit
   205→    const existingCount = await prisma.collection.count({
   206→      where: { userId },
   207→    });
   208→
   209→    if (existingCount >= COLLECTION_LIMITS.MAX_COLLECTIONS_PER_USER) {
   210→      return NextResponse.json(
   211→        {
   212→          success: false,
   213→          error: {
   214→            code: 'LIMIT_EXCEEDED',
   215→            message: `Maximum ${COLLECTION_LIMITS.MAX_COLLECTIONS_PER_USER} collections allowed`,
   216→          },
   217→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   218→        },
   219→        { status: 400 }
   220→      );
   221→    }
   222→
   223→    // Check for duplicate name (case-insensitive)
   224→    const existingCollection = await prisma.collection.findFirst({
   225→      where: {
   226→        userId,
   227→        name: { equals: name, mode: 'insensitive' },
   228→      },
   229→    });
   230→
   231→    if (existingCollection) {
   232→      return NextResponse.json(
   233→        {
   234→          success: false,
   235→          error: {
   236→            code: 'DUPLICATE_NAME',
   237→            message: 'A collection with this name already exists',
   238→          },
   239→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   240→        },
   241→        { status: 409 }
   242→      );
   243→    }
   244→
   245→    // Generate unique slug for the collection
   246→    const slug = await generateUniqueSlug(userId, name);
   247→
   248→    // Create collection with auto-like (user likes their own collection)
   249→    const collection = await prisma.$transaction(async (tx) => {
   250→      const newCollection = await tx.collection.create({
   251→        data: {
   252→          userId,
   253→          name,
   254→          slug,
   255→          description: description || null,
   256→          isPublic,
   257→          likeCount: 1, // Start with 1 like (from owner)
   258→        },
   259→      });
   260→
   261→      // Auto-like the collection
   262→      await tx.collectionLike.create({
   263→        data: {
   264→          userId,
   265→          collectionId: newCollection.id,
   266→        },
   267→      });
   268→
   269→      return newCollection;
   270→    });
   271→
   272→    // Log activity (fire-and-forget)
   273→    logActivity({
   274→      userId,
   275→      type: 'COLLECTION_CREATED',
   276→      targetName: collection.name,
   277→      targetType: 'collection',
   278→      collectionId: collection.id,
   279→    });
   280→
   281→    return NextResponse.json(
   282→      {
   283→        success: true,
   284→        data: {
   285→          id: collection.id,
   286→          name: collection.name,
   287→          slug: collection.slug,
   288→          description: collection.description,
   289→          isPublic: collection.isPublic,
   290→          toolCount: 0,
   291→          createdAt: collection.createdAt,
   292→          updatedAt: collection.updatedAt,
   293→        },
   294→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   295→      },
   296→      { status: 201 }
   297→    );
   298→  } catch (error) {
   299→    console.error('[API Error] POST /api/collections:', error);
   300→    return NextResponse.json(
   301→      {
   302→        success: false,
   303→        error: { code: 'INTERNAL_ERROR', message: 'Failed to create collection' },
   304→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   305→      },
   306→      { status: 500 }
   307→    );
   308→  }
   309→}
