    33→/**
    34→ * GET /api/collections/[id]/tools
    35→ * List all tools in a collection
    36→ */
    37→export async function GET(
    38→  _request: NextRequest,
    39→  context: RouteContext
    40→): Promise<NextResponse<ApiResponse>> {
    41→  const requestId = crypto.randomUUID();
    42→  const { id: collectionId } = await context.params;
    43→
    44→  try {
    45→    // Check if collection exists and is accessible
    46→    const collection = await prisma.collection.findUnique({
    47→      where: { id: collectionId },
    48→      select: { id: true, isPublic: true, userId: true },
    49→    });
    50→
    51→    if (!collection) {
    52→      return NextResponse.json(
    53→        {
    54→          success: false,
    55→          error: { code: 'NOT_FOUND', message: 'Collection not found' },
    56→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
    57→        },
    58→        { status: 404 }
    59→      );
    60→    }
    61→
    62→    // For private collections, check ownership
    63→    if (!collection.isPublic) {
    64→      const session = await auth.api.getSession({
    65→        headers: await headers(),
    66→      });
    67→
    68→      if (!session || collection.userId !== session.user.id) {
    69→        return NextResponse.json(
    70→          {
    71→            success: false,
    72→            error: { code: 'FORBIDDEN', message: 'Access denied' },
    73→            meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
    74→          },
    75→          { status: 403 }
    76→        );
    77→      }
    78→    }
    79→
    80→    // Fetch tools in the collection
    81→    const collectionTools = await prisma.collectionTool.findMany({
    82→      where: { collectionId },
    83→      include: {
    84→        tool: {
    85→          select: {
    86→            id: true,
    87→            name: true,
    88→            description: true,
    89→            parameters: true,
    90→            package: {
    91→              select: {
    92→                npmPackageName: true,
    93→                category: true,
    94→              },
    95→            },
    96→          },
    97→        },
    98→      },
    99→      orderBy: { position: 'asc' },
   100→    });
   101→
   102→    return NextResponse.json(
   103→      {
   104→        success: true,
   105→        data: collectionTools.map((ct) => ({
   106→          id: ct.id,
   107→          toolId: ct.toolId,
   108→          position: ct.position,
   109→          note: ct.note,
   110→          addedAt: ct.addedAt,
   111→          tool: ct.tool,
   112→        })),
   113→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
   114→      },
   115→      { status: 200 }
   116→    );
   117→  } catch (error) {
