     1→/**
     2→ * Collection factory for integration tests
     3→ *
     4→ * Creates test collections with auto-generated test prefixes
     5→ * and tracks them for cleanup.
     6→ */
     7→
     8→import type { ApiClient } from '../api-client';
     9→import type { TestDataTracker } from '../cleanup';
    10→
    11→export interface CreateCollectionOptions {
    12→  slug?: string;
    13→  name?: string;
    14→  description?: string;
    15→  isPublic?: boolean;
    16→  toolIds?: string[];
    17→}
    18→
    19→export interface CollectionFactoryResult {
    20→  id: string;
    21→  slug: string;
    22→  name: string;
    23→  description: string | null;
    24→  isPublic: boolean;
    25→  toolCount?: number;
    26→}
    27→
    28→/**
    29→ * Create a collection factory bound to a specific API client and tracker
    30→ */
    31→export function createCollectionFactory(api: ApiClient, tracker: TestDataTracker) {
    32→  let counter = 0;
    33→
    34→  return {
    35→    /**
    36→     * Create a new test collection
    37→     */
    38→    async create(options: CreateCollectionOptions = {}): Promise<CollectionFactoryResult> {
    39→      counter++;
    40→      const timestamp = Date.now();
    41→
    42→      const slug = options.slug || `test-collection-${timestamp}-${counter}`;
    43→      const name = options.name || `Test Collection ${timestamp}-${counter}`;
    44→
    45→      const result = await api.post<{ success: boolean; data: CollectionFactoryResult }>(
    46→        '/api/collections',
    47→        {
    48→          slug,
    49→          name,
    50→          description: options.description ?? 'Integration test collection',
    51→          isPublic: options.isPublic ?? true,
    52→        }
    53→      );
    54→
    55→      if (!result.ok) {
    56→        const errorResult = result as { error: string; status: number };
    57→        throw new Error(
    58→          `Failed to create collection: ${errorResult.error} (status: ${errorResult.status})`
    59→        );
    60→      }
    61→
    62→      const collection = result.data.data;
    63→      tracker.trackCollection(collection.id);
    64→
    65→      // Add tools if specified
    66→      if (options.toolIds && options.toolIds.length > 0) {
    67→        for (const toolId of options.toolIds) {
    68→          await api.post(`/api/collections/${collection.id}/tools`, { toolId });
    69→        }
    70→      }
    71→
    72→      return collection;
    73→    },
    74→
    75→    /**
    76→     * Create multiple test collections
    77→     */
    78→    async createMany(
    79→      count: number,
    80→      options: CreateCollectionOptions = {}
    81→    ): Promise<CollectionFactoryResult[]> {
    82→      const collections: CollectionFactoryResult[] = [];
    83→      for (let i = 0; i < count; i++) {
    84→        const collection = await this.create({
    85→          ...options,
    86→          slug: options.slug ? `${options.slug}-${i}` : undefined,
    87→          name: options.name ? `${options.name} ${i}` : undefined,
    88→        });
    89→        collections.push(collection);
    90→      }
    91→      return collections;
    92→    },
    93→
    94→    /**
    95→     * Get a collection by ID
    96→     */
    97→    async get(id: string): Promise<CollectionFactoryResult | null> {
    98→      const result = await api.get<{ success: boolean; data: CollectionFactoryResult }>(
    99→        `/api/collections/${id}`
   100→      );
   101→      if (!result.ok) {
   102→        return null;
   103→      }
   104→      return result.data.data;
   105→    },
   106→
   107→    /**
   108→     * Update a collection
   109→     */
   110→    async update(
   111→      id: string,
   112→      updates: Partial<CreateCollectionOptions>
   113→    ): Promise<CollectionFactoryResult> {
   114→      const result = await api.patch<{ success: boolean; data: CollectionFactoryResult }>(
   115→        `/api/collections/${id}`,
   116→        updates
   117→      );
   118→      if (!result.ok) {
   119→        throw new Error(`Failed to update collection: ${(result as { error: string }).error}`);
   120→      }
   121→      return result.data.data;
   122→    },
   123→
   124→    /**
   125→     * Delete a collection
   126→     */
   127→    async delete(id: string): Promise<void> {
   128→      const result = await api.delete(`/api/collections/${id}`);
   129→      if (!result.ok) {
   130→        throw new Error(`Failed to delete collection: ${(result as { error: string }).error}`);
   131→      }
   132→    },
   133→
   134→    /**
   135→     * Add a tool to a collection
   136→     */
   137→    async addTool(collectionId: string, toolId: string): Promise<void> {
   138→      const result = await api.post(`/api/collections/${collectionId}/tools`, { toolId });
   139→      if (!result.ok) {
   140→        throw new Error(`Failed to add tool to collection: ${(result as { error: string }).error}`);
   141→      }
   142→    },
   143→
   144→    /**
   145→     * Remove a tool from a collection
   146→     */
   147→    async removeTool(collectionId: string, toolId: string): Promise<void> {
   148→      const result = await api.delete(`/api/collections/${collectionId}/tools/${toolId}`);
   149→      if (!result.ok) {
   150→        throw new Error(
   151→          `Failed to remove tool from collection: ${(result as { error: string }).error}`
   152→        );
   153→      }
   154→    },
   155→  };
   156→}
   157→
   158→export type CollectionFactory = ReturnType<typeof createCollectionFactory>;
   159→

