     1→/**
     2→ * Simulation history endpoint
     3→ * Returns recent simulations for a tool with token usage data
     4→ */
     5→
     6→import { prisma } from '@tpmjs/db';
     7→import { type NextRequest, NextResponse } from 'next/server';
     8→
     9→/**
    10→ * GET /api/tools/simulations/[...slug]
    11→ * Returns the last 10 simulations for a tool
    12→ *
    13→ * Slug can be:
    14→ * - Tool ID (single slug)
    15→ * - Package name + export name (multiple slugs)
    16→ */
    17→export async function GET(
    18→  _request: NextRequest,
    19→  { params }: { params: Promise<{ slug: string[] }> }
    20→) {
    21→  const { slug } = await params;
    22→
    23→  try {
    24→    let tool;
    25→
    26→    if (slug.length === 1) {
    27→      // Single slug - treat as tool ID
    28→      tool = await prisma.tool.findUnique({
    29→        where: { id: slug[0] || '' },
    30→        select: { id: true },
    31→      });
    32→    } else {
    33→      // Multiple slugs - treat as packageName/name
    34→      const packageName = decodeURIComponent(slug.slice(0, -1).join('/'));
    35→      const name = decodeURIComponent(slug[slug.length - 1] || '');
    36→
    37→      tool = await prisma.tool.findFirst({
    38→        where: {
    39→          package: { npmPackageName: packageName },
    40→          name: name,
    41→        },
    42→        select: { id: true },
    43→      });
    44→    }
    45→
    46→    if (!tool) {
    47→      return NextResponse.json({ error: 'Tool not found' }, { status: 404 });
    48→    }
    49→
    50→    // Fetch recent simulations with token usage
    51→    const simulations = await prisma.simulation.findMany({
    52→      where: { toolId: tool.id },
    53→      include: {
    54→        tokenUsage: true,
    55→      },
    56→      orderBy: { createdAt: 'desc' },
    57→      take: 10,
    58→    });
    59→
    60→    return NextResponse.json({ simulations });
    61→  } catch (error) {
    62→    console.error('Simulations endpoint error:', error);
    63→    return NextResponse.json(
    64→      {
    65→        error: error instanceof Error ? error.message : 'Internal server error',
    66→      },
    67→      { status: 500 }
    68→    );
    69→  }
    70→}
