    46→/**
    47→ * Track API usage (fire and forget - non-blocking)
    48→ *
    49→ * This function returns immediately and tracks usage in the background.
    50→ * Errors are logged but don't affect the calling code.
    51→ *
    52→ * @param event - Usage event data
    53→ *
    54→ * @example
    55→ * trackUsage({
    56→ *   apiKeyId: auth.apiKeyId,
    57→ *   userId: auth.userId,
    58→ *   endpoint: '/api/mcp/...',
    59→ *   method: 'POST',
    60→ *   statusCode: 200,
    61→ *   latencyMs: 150,
    62→ *   resourceType: 'mcp',
    63→ *   resourceId: collectionId,
    64→ * });
    65→ */
    66→export function trackUsage(event: UsageEvent): void {
    67→  // Fire and forget - don't await
    68→  trackUsageAsync(event).catch((error) => {
    69→    console.error('[Usage Tracking] Error tracking usage:', error);
    70→  });
    71→}
