   177→      .replace(/\/[a-z0-9]{20,}/gi, '/:id')
   178→      // Replace numeric IDs
   179→      .replace(/\/\d+/g, '/:id')
   180→      // Limit length
   181→      .substring(0, 100)
   182→  );
   183→}
