   185→/**
   186→ * Create a usage tracker wrapper for route handlers
   187→ *
   188→ * This makes it easy to track usage in route handlers.
   189→ *
   190→ * @param userId - User ID
   191→ * @param apiKeyId - Optional API key ID
   192→ * @returns Object with track method and helper functions
   193→ *
   194→ * @example
   195→ * const tracker = createUsageTracker(auth.userId, auth.apiKeyId);
   196→ * tracker.track({
   197→ *   endpoint: '/api/mcp/...',
   198→ *   method: 'POST',
   199→ *   statusCode: 200,
   200→ *   latencyMs: 150,
   201→ * });
   202→ */
   203→export function createUsageTracker(userId: string, apiKeyId?: string) {
   204→  const startTime = Date.now();
   205→
   206→  return {
   207→    /**
   208→     * Track a usage event
   209→     */
   210→    track(
   211→      event: Omit<UsageEvent, 'userId' | 'apiKeyId'> & {
   212→        userId?: string;
   213→        apiKeyId?: string;
   214→      }
   215→    ) {
   216→      trackUsage({
   217→        ...event,
   218→        userId: event.userId || userId,
   219→        apiKeyId: event.apiKeyId || apiKeyId,
   220→      });
   221→    },
   222→
   223→    /**
   224→     * Track completion with automatic latency calculation
   225→     */
   226→    trackCompletion(
   227→      event: Omit<UsageEvent, 'userId' | 'apiKeyId' | 'latencyMs'> & {
   228→        userId?: string;
   229→        apiKeyId?: string;
   230→        latencyMs?: number;
   231→      }
   232→    ) {
   233→      trackUsage({
   234→        ...event,
   235→        userId: event.userId || userId,
   236→        apiKeyId: event.apiKeyId || apiKeyId,
   237→        latencyMs: event.latencyMs || Date.now() - startTime,
   238→      });
   239→    },
   240→
   241→    /**
   242→     * Get elapsed time since tracker creation
   243→     */
   244→    getElapsedMs() {
   245→      return Date.now() - startTime;
   246→    },
   247→  };
   248→}
   249→
   250→/**
   251→ * Cleanup old usage records (called by cron job)
   252→ *
   253→ * Deletes individual records older than 30 days.
   254→ * Summaries are kept for longer-term analytics.
   255→ *
   256→ * @param daysToKeep - Number of days to keep records (default 30)
   257→ * @returns Number of records deleted
   258→ */
   259→export async function cleanupOldUsageRecords(daysToKeep = 30): Promise<number> {
   260→  const cutoff = new Date();
   261→  cutoff.setDate(cutoff.getDate() - daysToKeep);
   262→
   263→  const result = await prisma.apiUsageRecord.deleteMany({
   264→    where: {
   265→      createdAt: {
   266→        lt: cutoff,
   267→      },
   268→    },
   269→  });
   270→
   271→  return result.count;
   272→}
