    47→async function getUserByUsername(username: string) {
    48→  return withTimeout(
    49→    prisma.user.findUnique({
    50→      where: { username },
    51→      select: { id: true, username: true },
    52→    }),
    53→    DB_TIMEOUT_MS,
    54→    `Database query timed out after ${DB_TIMEOUT_MS}ms`
    55→  );
    56→}
