   133→async function handleHttpTransport(
   134→  request: NextRequest,
   135→  collectionId: string,
   136→  collectionName: string,
   137→  isOwner: boolean
   138→): Promise<NextResponse> {
   139→  let body: JsonRpcRequest;
   140→  try {
   141→    body = await request.json();
   142→  } catch {
   143→    return NextResponse.json(
   144→      { jsonrpc: '2.0', error: { code: -32700, message: 'Parse error' }, id: null },
