   153→/**
   154→ * POST /api/mcp/[username]/[slug]/sse
   155→ * SSE transport - Server-Sent Events for streaming
   156→ */
   157→async function handleSseTransport(
   158→  request: NextRequest,
   159→  collectionId: string,
   160→  collectionName: string,
   161→  isOwner: boolean
   162→): Promise<Response> {
   163→  let body: JsonRpcRequest;
   164→  try {
   165→    body = await request.json();
   166→  } catch {
   167→    return new Response(
   168→      `data: ${JSON.stringify({ jsonrpc: '2.0', error: { code: -32700, message: 'Parse error' }, id: null })}\n\n`,
   169→      {
   170→        status: 400,
   171→        headers: {
   172→          'Content-Type': 'text/event-stream',
   173→          'Cache-Control': 'no-cache',
   174→          Connection: 'keep-alive',
   175→        },
   176→      }
   177→    );
   178→  }
   179→
   180→  const response = await processJsonRpcRequest(collectionId, collectionName, body, isOwner);
   181→
   182→  // For SSE, we send the response as an event and then close
   183→  const encoder = new TextEncoder();
   184→  const stream = new ReadableStream({
   185→    start(controller) {
   186→      // Send the JSON-RPC response as an SSE event
   187→      const eventData = `data: ${JSON.stringify(response)}\n\n`;
   188→      controller.enqueue(encoder.encode(eventData));
   189→      controller.close();
   190→    },
   191→  });
   192→
   193→  return new Response(stream, {
   194→    headers: {
   195→      'Content-Type': 'text/event-stream',
   196→      'Cache-Control': 'no-cache',
   197→      Connection: 'keep-alive',
   198→    },
   199→  });
   200→}
