   206→function handleSseGet(
   207→  username: string,
   208→  slug: string,
   209→  collectionName: string,
   210→  collectionDescription: string | null
   211→): Response {
   212→  const encoder = new TextEncoder();
   213→  const stream = new ReadableStream({
   214→    start(controller) {
   215→      // Send server info as initial event
   216→      const serverInfo = {
   217→        type: 'server_info',
   218→        name: `TPMJS: ${collectionName}`,
   219→        description: collectionDescription,
   220→        protocol: 'mcp',
   221→        transport: 'sse',
   222→        endpoint: `/api/mcp/${username}/${slug}/sse`,
   223→      };
   224→      const eventData = `data: ${JSON.stringify(serverInfo)}\n\n`;
   225→      controller.enqueue(encoder.encode(eventData));
   226→      // Keep connection open for future events
   227→    },
   228→  });
   229→
   230→  return new Response(stream, {
   231→    headers: {
   232→      'Content-Type': 'text/event-stream',
   233→      'Cache-Control': 'no-cache',
   234→      Connection: 'keep-alive',
   235→    },
   236→  });
   237→}
