   439→    // First, find the user by username
   440→    const user = await getUserByUsername(username);
   441→
   442→    if (!user) {
   443→      return NextResponse.json(
   444→        { error: `User '${username}' not found. Check the username in your MCP endpoint URL.` },
   445→        { status: 404 }
