   168→          tools: {
   169→            include: { tool: { include: { package: true } } },
   170→          },
   171→        },
   172→      }),
   173→      DB_TIMEOUT_MS,
   174→      'Database query timed out'
   175→    );
   176→
   177→    // Try all possible package name and tool name combinations
   178→    // This handles both old format (full package name) and new shortened format
