   286→/**
   287→ * Handle a bridge tool call by routing it through the user's bridge connection
   288→ */
   289→async function handleBridgeToolCall(
   290→  collectionId: string,
   291→  serverId: string,
   292→  toolName: string,
   293→  args: Record<string, unknown>,
   294→  requestId: JsonRpcId
   295→): Promise<JsonRpcResponse> {
   296→  try {
   297→    // Get the collection's owner and their bridge connection
   298→    const collection = await withTimeout(
   299→      prisma.collection.findUnique({
   300→        where: { id: collectionId },
   301→        include: {
   302→          bridgeTools: {
   303→            where: { serverId, toolName },
   304→          },
   305→          user: {
   306→            include: { bridgeConnection: true },
   307→          },
   308→        },
   309→      }),
   310→      DB_TIMEOUT_MS,
   311→      'Database query timed out'
   312→    );
   313→
   314→    if (!collection) {
   315→      return {
   316→        jsonrpc: '2.0',
   317→        id: requestId,
   318→        error: { code: -32602, message: 'Collection not found' },
   319→      };
   320→    }
   321→
   322→    // Verify the bridge tool exists in the collection
   323→    const bridgeTool = collection.bridgeTools[0];
   324→    if (!bridgeTool) {
   325→      return {
   326→        jsonrpc: '2.0',
   327→        id: requestId,
   328→        error: {
   329→          code: -32602,
   330→          message: `Bridge tool not found in collection: ${serverId}/${toolName}`,
   331→        },
   332→      };
   333→    }
   334→
   335→    // Verify the user has an active bridge connection
   336→    const bridgeConnection = collection.user.bridgeConnection;
   337→    if (!bridgeConnection || bridgeConnection.status !== 'connected') {
   338→      return {
   339→        jsonrpc: '2.0',
   340→        id: requestId,
   341→        result: {
   342→          content: [
   343→            {
   344→              type: 'text',
   345→              text: 'Error: Bridge is not connected. Start the bridge CLI to use bridge tools.',
   346→            },
   347→          ],
   348→          isError: true,
   349→        },
   350→      };
   351→    }
   352→
   353→    // Check if the bridge is stale (not seen in 2 minutes)
   354→    if (bridgeConnection.lastSeen) {
   355→      const staleThreshold = 2 * 60 * 1000; // 2 minutes
   356→      if (Date.now() - bridgeConnection.lastSeen.getTime() > staleThreshold) {
   357→        return {
   358→          jsonrpc: '2.0',
   359→          id: requestId,
   360→          result: {
   361→            content: [
   362→              {
   363→                type: 'text',
   364→                text: 'Error: Bridge connection appears stale. Please check if the bridge CLI is running.',
   365→              },
   366→            ],
   367→            isError: true,
   368→          },
   369→        };
   370→      }
   371→    }
   372→
   373→    // Generate a unique call ID
   374→    const callId = `${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
   375→
   376→    // Queue the tool call for the bridge to pick up
   377→    queueBridgeToolCall(collection.user.id, callId, serverId, toolName, args);
   378→
   379→    // Wait for the result (with 5 minute timeout)
   380→    const result = await waitForBridgeResult(callId, 300000);
   381→
   382→    if (result.error) {
   383→      return {
   384→        jsonrpc: '2.0',
   385→        id: requestId,
   386→        result: {
   387→          content: [{ type: 'text', text: `Error: ${result.error.message}` }],
   388→          isError: true,
   389→        },
   390→      };
   391→    }
   392→
   393→    // Format the result
   394→    const content = result.result as { content?: unknown[]; isError?: boolean } | undefined;
   395→    if (content?.content) {
   396→      return {
   397→        jsonrpc: '2.0',
   398→        id: requestId,
   399→        result: {
   400→          content: content.content,
   401→          isError: content.isError,
   402→        },
   403→      };
   404→    }
   405→
   406→    return {
   407→      jsonrpc: '2.0',
   408→      id: requestId,
   409→      result: {
   410→        content: [
   411→          {
   412→            type: 'text',
   413→            text:
   414→              typeof result.result === 'string'
   415→                ? result.result
   416→                : JSON.stringify(result.result, null, 2),
   417→          },
   418→        ],
   419→      },
   420→    };
   421→  } catch (error) {
   422→    console.error('[MCP bridge tool call] Error:', error);
   423→    return {
   424→      jsonrpc: '2.0',
   425→      id: requestId,
   426→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
   427→    };
   428→  }
   429→}
