    19→  { params }: { params: Promise<{ slug: string[] }> }
    20→) {
    21→  const { slug } = await params;
    22→
    23→  try {
    24→    let tool;
    25→
    26→    if (slug.length === 1) {
    27→      // Single slug - treat as tool ID
    28→      tool = await prisma.tool.findUnique({
    29→        where: { id: slug[0] || '' },
    30→        select: { id: true },
    31→      });
    32→    } else {
    33→      // Multiple slugs - treat as packageName/name
    34→      const packageName = decodeURIComponent(slug.slice(0, -1).join('/'));
    35→      const name = decodeURIComponent(slug[slug.length - 1] || '');
    36→
    37→      tool = await prisma.tool.findFirst({
    38→        where: {
    39→          package: { npmPackageName: packageName },
    40→          name: name,
    41→        },
    42→        select: { id: true },
