     1→import { prisma } from '@tpmjs/db';
     2→import type { TpmjsEnv } from '@tpmjs/types/tpmjs';
     3→import { queueBridgeToolCall, waitForBridgeResult } from '~/app/api/bridge/route';
     4→import { executeWithExecutor, parseExecutorConfig } from '../executors';
     5→import {
     6→  type BridgeTool,
     7→  convertBridgeToolToMcp,
     8→  convertToMcpTool,
     9→  parseToolName,
    10→} from './tool-converter';
    11→
    12→const DB_TIMEOUT_MS = 10000; // 10 second timeout for database queries
    13→
    14→type JsonRpcId = string | number | null;
    15→
    16→interface JsonRpcResponse {
    17→  jsonrpc: '2.0';
    18→  id: JsonRpcId;
    19→  result?: unknown;
    20→  error?: { code: number; message: string; data?: unknown };
    21→}
    22→
    23→/**
    24→ * Wrap a promise with a timeout
    25→ */
    26→function withTimeout<T>(promise: Promise<T>, ms: number, errorMessage: string): Promise<T> {
    27→  return Promise.race([
    28→    promise,
    29→    new Promise<T>((_, reject) => setTimeout(() => reject(new Error(errorMessage)), ms)),
    30→  ]);
    31→}
    32→
    33→/**
    34→ * Handle MCP initialize request
    35→ */
    36→export function handleInitialize(collectionName: string, requestId: JsonRpcId): JsonRpcResponse {
    37→  return {
    38→    jsonrpc: '2.0',
    39→    id: requestId,
    40→    result: {
    41→      protocolVersion: '2024-11-05',
    42→      serverInfo: {
    43→        name: `TPMJS: ${collectionName}`,
    44→        version: '1.0.0',
    45→      },
    46→      capabilities: { tools: {} },
    47→    },
    48→  };
    49→}
    50→
    51→/**
    52→ * Handle MCP tools/list request
    53→ */
    54→export async function handleToolsList(
    55→  collectionId: string,
    56→  requestId: JsonRpcId
    57→): Promise<JsonRpcResponse> {
    58→  try {
    59→    const collection = await withTimeout(
    60→      prisma.collection.findUnique({
    61→        where: { id: collectionId },
    62→        include: {
    63→          tools: {
    64→            include: { tool: { include: { package: true } } },
    65→            orderBy: { position: 'asc' },
    66→          },
    67→          bridgeTools: true,
    68→          user: {
    69→            include: {
    70→              bridgeConnection: true,
    71→            },
    72→          },
    73→        },
    74→      }),
    75→      DB_TIMEOUT_MS,
    76→      'Database query timed out'
    77→    );
    78→
    79→    // Convert registry tools to MCP format
    80→    const registryTools = collection?.tools.map((ct) => convertToMcpTool(ct.tool)) ?? [];
    81→
    82→    // Convert bridge tools to MCP format
    83→    const bridgeTools: ReturnType<typeof convertBridgeToolToMcp>[] = [];
    84→
    85→    if (collection?.bridgeTools.length && collection.user.bridgeConnection) {
    86→      const bridgeConnection = collection.user.bridgeConnection;
    87→      const availableBridgeTools = (bridgeConnection.tools as unknown as BridgeTool[]) || [];
    88→
    89→      // Only include bridge tools if bridge is connected
    90→      if (bridgeConnection.status === 'connected') {
    91→        for (const collectionBridgeTool of collection.bridgeTools) {
    92→          // Find the tool definition from the bridge connection
    93→          const bridgeTool = availableBridgeTools.find(
    94→            (bt) =>
    95→              bt.serverId === collectionBridgeTool.serverId &&
    96→              bt.name === collectionBridgeTool.toolName
    97→          );
    98→
    99→          if (bridgeTool) {
   100→            bridgeTools.push(convertBridgeToolToMcp(bridgeTool, collectionBridgeTool.displayName));
   101→          }
   102→        }
   103→      }
   104→    }
   105→
   106→    return {
   107→      jsonrpc: '2.0',
   108→      id: requestId,
   109→      result: { tools: [...registryTools, ...bridgeTools] },
   110→    };
   111→  } catch (error) {
   112→    console.error('[MCP tools/list] Error:', error);
   113→    return {
   114→      jsonrpc: '2.0',
   115→      id: requestId,
   116→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
   117→    };
   118→  }
   119→}
   120→
   121→interface ToolsCallParams {
   122→  name: string;
   123→  arguments?: Record<string, unknown>;
   124→  env?: Record<string, string>; // Caller-provided env vars for non-owners
   125→}
   126→
   127→/**
   128→ * Handle MCP tools/call request
   129→ * @param callerEnvVars - Optional env vars from caller (non-owner accessing public collection)
   130→ *                        When provided, these are used INSTEAD of collection's stored env vars
   131→ */
   132→export async function handleToolsCall(
   133→  collectionId: string,
   134→  params: ToolsCallParams,
   135→  requestId: JsonRpcId,
   136→  callerEnvVars?: Record<string, string>
   137→): Promise<JsonRpcResponse> {
   138→  try {
   139→    const parsed = parseToolName(params.name);
   140→    if (!parsed) {
   141→      return {
   142→        jsonrpc: '2.0',
   143→        id: requestId,
   144→        error: { code: -32602, message: `Invalid tool name: ${params.name}` },
   145→      };
   146→    }
   147→
   148→    // Handle bridge tool calls
   149→    if (parsed.type === 'bridge') {
   150→      return handleBridgeToolCall(
   151→        collectionId,
   152→        parsed.serverId,
   153→        parsed.toolName,
   154→        params.arguments ?? {},
   155→        requestId
   156→      );
   157→    }
   158→
   159→    // Handle registry tool calls
   160→    // Verify tool exists in collection and get executor config
   161→    const collection = await withTimeout(
   162→      prisma.collection.findUnique({
   163→        where: { id: collectionId },
   164→        select: {
   165→          executorType: true,
   166→          executorConfig: true,
   167→          envVars: true,
   168→          tools: {
   169→            include: { tool: { include: { package: true } } },
   170→          },
   171→        },
   172→      }),
   173→      DB_TIMEOUT_MS,
   174→      'Database query timed out'
   175→    );
   176→
   177→    // Try all possible package name and tool name combinations
   178→    // This handles both old format (full package name) and new shortened format
   179→    type CollectionTool = NonNullable<typeof collection>['tools'][number];
   180→    let collectionTool: CollectionTool | undefined;
   181→
   182→    for (const pkgName of parsed.possiblePackages) {
   183→      for (const toolName of parsed.possibleToolNames) {
   184→        collectionTool = collection?.tools.find(
   185→          (ct) => ct.tool.package.npmPackageName === pkgName && ct.tool.name === toolName
   186→        );
   187→        if (collectionTool) break;
   188→      }
   189→      if (collectionTool) break;
   190→    }
   191→
   192→    if (!collectionTool) {
   193→      return {
   194→        jsonrpc: '2.0',
   195→        id: requestId,
   196→        error: { code: -32602, message: `Tool not found in collection: ${params.name}` },
   197→      };
   198→    }
   199→
   200→    // Get the actual package name and version that matched
   201→    const actualPackageName = collectionTool.tool.package.npmPackageName;
   202→    const actualVersion = collectionTool.tool.package.npmVersion;
   203→
   204→    // When caller provides env vars (non-owner), validate required env vars
   205→    if (callerEnvVars !== undefined) {
   206→      const packageEnv = collectionTool.tool.package.env as TpmjsEnv[] | null;
   207→      if (packageEnv && Array.isArray(packageEnv)) {
   208→        const missingVars = packageEnv.filter(
   209→          (env) => env.required !== false && !env.default && !callerEnvVars[env.name]
   210→        );
   211→
   212→        if (missingVars.length > 0) {
   213→          return {
   214→            jsonrpc: '2.0',
   215→            id: requestId,
   216→            error: {
   217→              code: -32602,
   218→              message: 'Missing required environment variables',
   219→              data: {
   220→                missingVars: missingVars.map((e) => ({
   221→                  name: e.name,
   222→                  description: e.description,
   223→                })),
   224→              },
   225→            },
   226→          };
   227→        }
   228→      }
   229→    }
   230→
   231→    // Resolve executor configuration (collection config only for MCP - no agent context)
   232→    const executorConfig = parseExecutorConfig(
   233→      collection?.executorType,
   234→      collection?.executorConfig
   235→    );
   236→
   237→    // Execute via resolved executor
   238→    // Use caller-provided env vars if given (non-owner), otherwise use collection's stored env vars
   239→    const effectiveEnvVars = callerEnvVars ?? (collection?.envVars as Record<string, string>) ?? {};
