     1→import { Args, Command, Flags } from '@oclif/core';
     2→import { getClient } from '../../lib/api-client.js';
     3→import { createOutput } from '../../lib/output.js';
     4→
     5→export default class CollectionAdd extends Command {
     6→  static description = 'Add tools to a collection';
     7→
     8→  static examples = [
     9→    '<%= config.bin %> <%= command.id %> my-collection tool-id-1',
    10→    '<%= config.bin %> <%= command.id %> my-collection tool-id-1 tool-id-2 tool-id-3',
    11→  ];
    12→
    13→  static strict = false; // Allow variable number of arguments
    14→
    15→  static flags = {
    16→    json: Flags.boolean({
    17→      description: 'Output in JSON format',
    18→      default: false,
    19→    }),
    20→    verbose: Flags.boolean({
    21→      char: 'v',
    22→      description: 'Show verbose output',
    23→      default: false,
    24→    }),
    25→  };
    26→
    27→  static args = {
    28→    collection: Args.string({
    29→      description: 'Collection ID or slug',
    30→      required: true,
    31→    }),
    32→  };
    33→
    34→  async run(): Promise<void> {
    35→    const { args, argv, flags } = await this.parse(CollectionAdd);
    36→    const output = createOutput(flags);
    37→    const client = getClient();
    38→
    39→    if (!client.isAuthenticated()) {
    40→      output.error('Not authenticated. Run `tpm auth login` first.');
    41→      return;
    42→    }
    43→
    44→    // Get tool IDs from remaining arguments
    45→    const toolIds = argv.slice(1) as string[];
    46→
    47→    if (toolIds.length === 0) {
    48→      output.error('Please specify at least one tool ID to add');
    49→      output.text('Example: tpm collection add my-collection tool-id-1 tool-id-2');
    50→      return;
    51→    }
    52→
    53→    const spinner = output.spinner(`Adding ${toolIds.length} tool(s)...`);
    54→
    55→    try {
    56→      await client.addToolsToCollection(args.collection, toolIds);
    57→
    58→      spinner.stop();
    59→
    60→      if (flags.json) {
    61→        output.json({ success: true, added: toolIds.length, toolIds });
    62→        return;
    63→      }
    64→
    65→      output.success(`Added ${toolIds.length} tool(s) to collection`);
    66→      for (const toolId of toolIds) {
    67→        output.listItem(toolId);
    68→      }
    69→    } catch (error) {
    70→      spinner.fail('Failed to add tools');
    71→      output.error(
    72→        error instanceof Error ? error.message : 'Unknown error',
    73→        flags.verbose ? String(error) : undefined
    74→      );
    75→    }
    76→  }
    77→}
