     1→/**
     2→ * Agent Conversation Endpoint (ID-based version)
     3→ *
     4→ * POST: Send a message and stream the AI response
     5→ * GET: Retrieve conversation history
     6→ * DELETE: Delete a conversation
     7→ *
     8→ * This endpoint uses agent id directly for dashboard usage.
     9→ *
    10→ * Authentication: Supports both session auth and TPMJS API key auth.
    11→ * Requires 'agent:chat' scope for API key access.
    12→ */
    13→
    14→import { Prisma, prisma } from '@tpmjs/db';
    15→import type { AIProvider } from '@tpmjs/types/agent';
    16→import { SendMessageSchema } from '@tpmjs/types/agent';
    17→import type { LanguageModel, ModelMessage } from 'ai';
    18→import { type NextRequest, NextResponse } from 'next/server';
    19→import { decryptApiKey } from '@/lib/crypto/api-keys';
    20→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
    21→import { trackUsage } from '~/lib/api-keys/usage';
    22→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
    23→
    24→/**
    25→ * Rate limit for chat messages: 30 requests per minute
    26→ * This is stricter than default because chat involves expensive LLM calls
    27→ */
    28→const CHAT_RATE_LIMIT: RateLimitConfig = {
    29→  limit: 30,
    30→  windowSeconds: 60,
    31→};
    32→
    33→export const runtime = 'nodejs';
    34→export const dynamic = 'force-dynamic';
    35→export const maxDuration = 300; // 5 minutes for long agentic runs
    36→
    37→type RouteContext = {
    38→  params: Promise<{ id: string; conversationId: string }>;
    39→};
    40→
    41→/**
    42→ * Get AI provider SDK based on provider type
    43→ */
    44→async function getProviderModel(
    45→  provider: AIProvider,
    46→  modelId: string,
    47→  apiKey: string
    48→): Promise<LanguageModel> {
    49→  switch (provider) {
    50→    case 'OPENAI': {
    51→      const { createOpenAI } = await import('@ai-sdk/openai');
    52→      return createOpenAI({ apiKey })(modelId);
    53→    }
    54→    case 'ANTHROPIC': {
    55→      const { createAnthropic } = await import('@ai-sdk/anthropic');
    56→      return createAnthropic({ apiKey })(modelId);
    57→    }
    58→    case 'GOOGLE': {
    59→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
    60→      return createGoogleGenerativeAI({ apiKey })(modelId);
    61→    }
    62→    case 'GROQ': {
    63→      const { createGroq } = await import('@ai-sdk/groq');
    64→      return createGroq({ apiKey })(modelId);
    65→    }
    66→    case 'MISTRAL': {
    67→      const { createMistral } = await import('@ai-sdk/mistral');
    68→      return createMistral({ apiKey })(modelId);
    69→    }
    70→    default:
    71→      throw new Error(`Unsupported provider: ${provider}`);
    72→  }
    73→}
    74→
    75→/**
    76→ * POST /api/agents/[id]/conversation/[conversationId]
    77→ * Send a message and stream the AI response via SSE
    78→ */
    79→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
    80→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
    81→  const startTime = Date.now();
    82→
    83→  // Authenticate request (supports both session and API key)
    84→  const authResult = await authenticateRequest();
    85→
    86→  if (!authResult.authenticated) {
    87→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    88→  }
    89→
    90→  // Check scope for API key auth
    91→  if (authResult.authenticated && !authResult.isSessionAuth) {
    92→    if (!hasScope(authResult, 'agent:chat')) {
    93→      return NextResponse.json(
    94→        { error: 'API key does not have agent:chat scope' },
    95→        { status: 403 }
    96→      );
    97→    }
    98→  }
    99→
   100→  // Check rate limit (after auth so we can track by user if needed)
   101→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
   102→  if (rateLimitResponse) {
   103→    return rateLimitResponse;
   104→  }
   105→
   106→  const { id: agentId, conversationId } = await context.params;
   107→
   108→  try {
   109→    const body = await request.json();
   110→    const parsed = SendMessageSchema.safeParse(body);
   111→    if (!parsed.success) {
   112→      return NextResponse.json(
   113→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
   114→        { status: 400 }
   115→      );
   116→    }
   117→
   118→    // Fetch agent with all tool relations using agent ID
   119→    const { fetchAgentWithTools, buildAgentTools } = await import('@/lib/agents/build-tools');
   120→    const { getRequiredEnvVarsForAgent, getMissingEnvVars } = await import(
   121→      '@/lib/agents/env-helpers'
   122→    );
   123→    const agent = await fetchAgentWithTools(agentId);
   124→
   125→    if (!agent) {
   126→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
   127→    }
   128→
   129→    // Check ownership
   130→    const isOwner = authResult.userId === agent.userId;
   131→
   132→    // Non-owners can only access PUBLIC agents
   133→    if (!isOwner && !agent.isPublic) {
   134→      // Don't reveal that the agent exists - return 404
   135→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
   136→    }
   137→
   138→    // Map provider to expected key name format
   139→    const providerKeyNames: Record<string, string> = {
   140→      OPENAI: 'OPENAI_API_KEY',
   141→      ANTHROPIC: 'ANTHROPIC_API_KEY',
   142→      GOOGLE: 'GOOGLE_API_KEY',
   143→      GROQ: 'GROQ_API_KEY',
   144→      MISTRAL: 'MISTRAL_API_KEY',
   145→    };
   146→    const keyName = providerKeyNames[agent.provider];
   147→
   148→    if (!keyName) {
   149→      return NextResponse.json(
   150→        { success: false, error: `Unsupported provider: ${agent.provider}` },
   151→        { status: 400 }
   152→      );
   153→    }
   154→
   155→    let apiKey: string;
   156→    let callerEnvVars: Record<string, string> | undefined;
   157→
   158→    if (isOwner) {
   159→      // Owner: use stored encrypted keys
   160→      const userApiKey = await prisma.userApiKey.findUnique({
   161→        where: {
   162→          userId_keyName: {
   163→            userId: agent.userId,
   164→            keyName,
   165→          },
   166→        },
   167→      });
   168→
   169→      if (!userApiKey) {
   170→        return NextResponse.json(
   171→          {
   172→            success: false,
   173→            error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
   174→          },
   175→          { status: 400 }
   176→        );
   177→      }
   178→
   179→      // Decrypt the API key
   180→      apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
   181→      // callerEnvVars stays undefined - buildAgentTools will use agent's stored env vars
   182→    } else {
   183→      // Non-owner accessing public agent: must provide their own credentials
   184→      if (!parsed.data.providerApiKey) {
   185→        return NextResponse.json(
   186→          {
   187→            success: false,
   188→            error: 'Public agent access requires your own API key',
   189→            details: {
   190→              code: 'MISSING_PROVIDER_KEY',
   191→              requiredProvider: agent.provider,
   192→              hint: `Provide your ${agent.provider} API key in the 'providerApiKey' field`,
   193→            },
   194→          },
   195→          { status: 400 }
   196→        );
   197→      }
   198→
   199→      apiKey = parsed.data.providerApiKey;
   200→      callerEnvVars = parsed.data.env || {};
   201→
   202→      // Check for required environment variables
   203→      const requiredEnvVars = getRequiredEnvVarsForAgent(agent);
   204→      const missingEnvVars = getMissingEnvVars(requiredEnvVars, callerEnvVars);
   205→
   206→      if (missingEnvVars.length > 0) {
   207→        return NextResponse.json(
   208→          {
   209→            success: false,
   210→            error: 'Missing required environment variables',
   211→            details: {
   212→              code: 'MISSING_ENV_VARS',
   213→              missingVars: missingEnvVars.map((e) => ({
   214→                name: e.name,
   215→                description: e.description,
   216→              })),
   217→              hint: "Provide these variables in the 'env' field of your request",
   218→            },
   219→          },
   220→          { status: 400 }
   221→        );
   222→      }
   223→    }
   224→
   225→    // Get or create conversation
   226→    let conversation = await prisma.conversation.findUnique({
   227→      where: {
   228→        agentId_slug: {
   229→          agentId: agent.id,
   230→          slug: conversationId,
   231→        },
   232→      },
   233→    });
   234→
   235→    if (!conversation) {
   236→      conversation = await prisma.conversation.create({
   237→        data: {
   238→          agentId: agent.id,
   239→          slug: conversationId,
   240→          title: parsed.data.message.slice(0, 100),
   241→        },
   242→      });
   243→    }
   244→
   245→    // Fetch recent messages for context
   246→    const recentMessages = await prisma.message.findMany({
   247→      where: { conversationId: conversation.id },
   248→      orderBy: { createdAt: 'desc' },
   249→      take: agent.maxMessagesInContext,
   250→    });
   251→
   252→    // Reverse to get chronological order
   253→    recentMessages.reverse();
   254→
   255→    // Save user message
   256→    await prisma.message.create({
   257→      data: {
   258→        conversationId: conversation.id,
   259→        role: 'USER',
   260→        content: parsed.data.message,
   261→      },
   262→    });
   263→
   264→    // Build AI SDK messages from conversation history
   265→    const { streamText, stepCountIs } = await import('ai');
   266→
   267→    const messages: ModelMessage[] = [];
   268→
   269→    // Add system prompt if defined
   270→    if (agent.systemPrompt) {
   271→      messages.push({
   272→        role: 'system',
   273→        content: agent.systemPrompt,
   274→      });
   275→    }
   276→
   277→    // Build a set of tool call IDs that have corresponding tool results
   278→    // This is needed because AI SDK requires every tool call to have a matching tool result
   279→    const toolResultIds = new Set(
   280→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
   281→    );
   282→
   283→    // Add conversation history - properly format for AI SDK
   284→    for (const msg of recentMessages) {
   285→      if (msg.role === 'USER') {
   286→        messages.push({ role: 'user', content: msg.content });
   287→      } else if (msg.role === 'ASSISTANT') {
   288→        // For assistant messages with tool calls, include ToolCallParts in content
   289→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
   290→          // Only include tool calls that have matching tool results
   291→          // AI SDK fails if there's a tool call without a corresponding tool result
   292→          const validToolCalls = (
   293→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
   294→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
   295→
   296→          if (validToolCalls.length > 0) {
   297→            const toolCallParts = validToolCalls.map((tc) => ({
   298→              type: 'tool-call' as const,
   299→              toolCallId: tc.toolCallId,
   300→              toolName: tc.toolName,
   301→              input: tc.args,
   302→            }));
   303→            // Content includes text (if any) plus tool call parts
   304→            const content: Array<
   305→              | { type: 'text'; text: string }
   306→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
   307→            > = [];
   308→            if (msg.content) {
   309→              content.push({ type: 'text', text: msg.content });
   310→            }
   311→            content.push(...toolCallParts);
   312→            messages.push({
   313→              role: 'assistant',
   314→              content,
   315→            });
   316→          } else {
   317→            // All tool calls are missing results, just include text content
   318→            messages.push({
   319→              role: 'assistant',
   320→              content: msg.content || '',
   321→            });
   322→          }
   323→        } else {
   324→          messages.push({
   325→            role: 'assistant',
   326→            content: msg.content,
   327→          });
   328→        }
   329→      } else if (msg.role === 'TOOL') {
   330→        // Tool results use the 'tool' role with content array
   331→        messages.push({
   332→          role: 'tool',
   333→          content: [
   334→            {
   335→              type: 'tool-result' as const,
   336→              toolCallId: msg.toolCallId || '',
   337→              toolName: msg.toolName || '',
   338→              output: {
   339→                type: 'json' as const,
   340→                value: msg.toolResult,
   341→              },
   342→            },
   343→          ],
   344→        });
   345→      }
   346→    }
   347→
   348→    // Add new user message
   349→    messages.push({ role: 'user', content: parsed.data.message });
   350→
   351→    // Build tools from agent configuration
   352→    // Build tools - pass callerEnvVars if non-owner accessing public agent
   353→    const tools = buildAgentTools(agent, callerEnvVars);
   354→
   355→    // Get the provider model
   356→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
   357→
   358→    // Create SSE stream
   359→    const stream = new ReadableStream({
   360→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
   361→      async start(controller) {
   362→        const encoder = new TextEncoder();
   363→
   364→        const sendEvent = (event: string, data: unknown) => {
   365→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
   366→          controller.enqueue(encoder.encode(message));
   367→        };
   368→
   369→        try {
   370→          const startTime = Date.now();
   371→          let fullContent = '';
   372→          // Accumulate tool calls with their input args
   373→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
   374→            new Map();
   375→          // Collect tool results to save AFTER assistant message (for correct chronological order)
   376→          const pendingToolResults: Array<{
   377→            toolCallId: string;
   378→            toolName: string;
   379→            output: unknown;
   380→          }> = [];
   381→          let inputTokens = 0;
   382→          let outputTokens = 0;
   383→
   384→          // Stream the response with agentic loop control
   385→          const result = await streamText({
   386→            model,
   387→            messages,
   388→            tools,
   389→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
   390→            onChunk: async ({ chunk }) => {
   391→              // Stream tool calls as they come in and capture their inputs
   392→              if (chunk.type === 'tool-call') {
   393→                const input = 'args' in chunk ? chunk.args : chunk.input;
   394→
   395→                // Log tool call for debugging
   396→                console.log('[Agent] Tool call initiated:', {
   397→                  toolName: chunk.toolName,
   398→                  toolCallId: chunk.toolCallId,
   399→                  input: JSON.stringify(input).slice(0, 500),
   400→                });
   401→
   402→                // Store tool call with input for later persistence
   403→                toolCallsMap.set(chunk.toolCallId, {
   404→                  toolCallId: chunk.toolCallId,
   405→                  toolName: chunk.toolName,
   406→                  args: input,
   407→                });
   408→                sendEvent('tool_call', {
   409→                  toolCallId: chunk.toolCallId,
   410→                  toolName: chunk.toolName,
   411→                  input,
   412→                });
   413→              }
   414→            },
   415→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
   416→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
   417→              // Capture tool calls from step finish (backup in case onChunk missed any)
   418→              if (toolCalls && Array.isArray(toolCalls)) {
   419→                for (const tc of toolCalls) {
   420→                  if (!toolCallsMap.has(tc.toolCallId)) {
   421→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
   422→                    const args =
   423→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
   424→                    toolCallsMap.set(tc.toolCallId, {
   425→                      toolCallId: tc.toolCallId,
   426→                      toolName: tc.toolName,
   427→                      args,
   428→                    });
