   239→/**
   240→ * POST /api/mcp/[username]/[slug]/[transport]
   241→ * MCP JSON-RPC endpoint for tool execution
   242→ */
   243→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
   244→  const startTime = Date.now();
   245→  let authResult: Awaited<ReturnType<typeof authenticateRequest>> | null = null;
   246→
   247→  try {
   248→    const { username, slug, transport } = await context.params;
   249→
   250→    if (transport !== 'http' && transport !== 'sse') {
   251→      return NextResponse.json(
   252→        {
   253→          jsonrpc: '2.0',
   254→          error: { code: -32001, message: `Invalid transport: ${transport}` },
   255→          id: null,
   256→        },
   257→        { status: 400 }
   258→      );
   259→    }
   260→
   261→    // Authenticate the request
   262→    authResult = await authenticateRequest();
   263→
   264→    // Check if auth is required
   265→    if (REQUIRE_AUTH && !authResult.authenticated) {
   266→      return NextResponse.json(
   267→        {
   268→          jsonrpc: '2.0',
   269→          error: { code: -32000, message: authResult.error || 'Authentication required' },
   270→          id: null,
   271→        },
   272→        { status: 401 }
   273→      );
   274→    }
   275→
   276→    // Check scope if authenticated
   277→    if (authResult.authenticated && !hasScope(authResult, API_KEY_SCOPES.MCP_EXECUTE)) {
   278→      return NextResponse.json(
   279→        {
   280→          jsonrpc: '2.0',
   281→          error: { code: -32000, message: 'Missing required scope: mcp:execute' },
   282→          id: null,
   283→        },
   284→        { status: 403 }
   285→      );
   286→    }
   287→
   288→    // Rate limit if authenticated via API key
   289→    if (authResult.authenticated && authResult.apiKeyId) {
   290→      const rateLimitResult = await checkApiKeyRateLimit(
   291→        authResult.apiKeyId,
   292→        authResult.tier || 'FREE'
   293→      );
   294→
   295→      if (!rateLimitResult.allowed) {
   296→        return createRateLimitResponse(rateLimitResult);
   297→      }
   298→    }
   299→
   300→    // Log warning for unauthenticated requests (soft launch)
   301→    if (!authResult.authenticated && !REQUIRE_AUTH) {
   302→      console.warn(
   303→        `[MCP] Unauthenticated request to /${username}/${slug}/${transport} - ` +
   304→          'API key authentication will be required in a future update'
   305→      );
   306→    }
   307→
   308→    // First, find the user by username
   309→    const user = await getUserByUsername(username);
   310→
   311→    if (!user) {
   312→      return NextResponse.json(
   313→        {
   314→          jsonrpc: '2.0',
   315→          error: {
   316→            code: -32001,
   317→            message: `User '${username}' not found. Check the username in your MCP endpoint URL.`,
   318→          },
   319→          id: null,
   320→        },
   321→        { status: 404 }
   322→      );
   323→    }
   324→
   325→    // Then find the collection by user ID and slug/ID
   326→    const collection = await getCollectionByUserIdAndSlugOrId(user.id, slug);
   327→
   328→    if (!collection) {
   329→      return NextResponse.json(
   330→        {
   331→          jsonrpc: '2.0',
   332→          error: {
   333→            code: -32001,
   334→            message: `Collection '${slug}' not found for user '${username}'.`,
   335→          },
   336→          id: null,
   337→        },
   338→        { status: 404 }
   339→      );
   340→    }
   341→
   342→    // Authorization check:
   343→    // - Owners can always access their own collections (public or private)
   344→    // - Non-owners can access PUBLIC collections with their own env vars
   345→    const isOwner = authResult.userId === collection.userId;
   346→
   347→    if (!isOwner) {
   348→      if (!collection.isPublic) {
   349→        // Private collection, not the owner - don't reveal existence
   350→        return NextResponse.json(
   351→          { jsonrpc: '2.0', error: { code: -32001, message: 'Collection not found' }, id: null },
   352→          { status: 404 }
   353→        );
   354→      }
   355→      // Public collection - non-owners can access but must provide their own env vars
   356→      // The env vars are validated per-tool in handleToolsCall
   357→    }
   358→
   359→    let response: Response;
   360→    if (transport === 'sse') {
   361→      response = await handleSseTransport(request, collection.id, collection.name, isOwner);
   362→    } else {
   363→      response = await handleHttpTransport(request, collection.id, collection.name, isOwner);
   364→    }
   365→
   366→    // Track usage for authenticated requests
   367→    if (authResult.authenticated && authResult.userId) {
   368→      const clientMeta = await getClientMetadata();
   369→      trackUsage({
   370→        apiKeyId: authResult.apiKeyId,
   371→        userId: authResult.userId,
   372→        endpoint: `/api/mcp/${username}/${slug}/${transport}`,
   373→        method: 'POST',
   374→        statusCode: response.status,
   375→        latencyMs: Date.now() - startTime,
   376→        resourceType: 'mcp',
   377→        resourceId: collection.id,
   378→        userAgent: clientMeta.userAgent,
   379→        ipAddress: clientMeta.ipAddress,
   380→      });
   381→    }
   382→
   383→    // Add rate limit headers for authenticated requests
   384→    if (authResult.authenticated && authResult.apiKeyId) {
   385→      const rateLimitResult = await checkApiKeyRateLimit(
   386→        authResult.apiKeyId,
   387→        authResult.tier || 'FREE'
   388→      );
   389→      const headers = getRateLimitHeaders(rateLimitResult);
   390→      for (const [key, value] of Object.entries(headers)) {
   391→        response.headers.set(key, value);
   392→      }
   393→    }
   394→
   395→    return response;
   396→  } catch (error) {
   397→    console.error('[MCP POST] Error:', error);
   398→    const message = error instanceof Error ? error.message : 'Internal server error';
   399→
   400→    // Track error for authenticated requests
   401→    if (authResult?.authenticated && authResult.userId) {
   402→      const { username, slug, transport } = await context.params;
   403→      const clientMeta = await getClientMetadata();
   404→      trackUsage({
   405→        apiKeyId: authResult.apiKeyId,
   406→        userId: authResult.userId,
   407→        endpoint: `/api/mcp/${username}/${slug}/${transport}`,
   408→        method: 'POST',
   409→        statusCode: 500,
   410→        latencyMs: Date.now() - startTime,
   411→        resourceType: 'mcp',
   412→        errorCode: 'INTERNAL_ERROR',
   413→        errorMessage: message,
   414→        userAgent: clientMeta.userAgent,
   415→        ipAddress: clientMeta.ipAddress,
   416→      });
   417→    }
   418→
   419→    return NextResponse.json(
   420→      { jsonrpc: '2.0', error: { code: -32603, message }, id: null },
   421→      { status: 500 }
   422→    );
   423→  }
   424→}
