     1→/**
     2→ * Executor Resolution Logic
     3→ *
     4→ * Handles the cascade resolution for hot-swappable executors:
     5→ * Agent Config → Collection Config → System Default
     6→ */
     7→
     8→import { executePackage } from '@tpmjs/package-executor';
     9→import type {
    10→  ExecuteToolRequest,
    11→  ExecuteToolResponse,
    12→  ExecutorConfig,
    13→  ExecutorHealthResponse,
    14→} from '@tpmjs/types/executor';
    15→
    16→const DEFAULT_TIMEOUT = 300000; // 5 minutes for custom executors
    17→
    18→/**
    19→ * Resolve executor configuration using cascade:
    20→ * Agent Config → Collection Config → System Default
    21→ *
    22→ * @param agentConfig - Executor config from Agent (highest priority)
    23→ * @param collectionConfig - Executor config from Collection (medium priority)
    24→ * @returns Resolved executor configuration
    25→ */
    26→export function resolveExecutorConfig(
    27→  agentConfig: ExecutorConfig | null | undefined,
    28→  collectionConfig: ExecutorConfig | null | undefined
    29→): ExecutorConfig {
    30→  // Agent config takes precedence
    31→  if (agentConfig && agentConfig.type !== 'default') {
    32→    return agentConfig;
    33→  }
    34→
    35→  // Fall back to collection config
    36→  if (collectionConfig && collectionConfig.type !== 'default') {
    37→    return collectionConfig;
    38→  }
    39→
    40→  // System default
    41→  return { type: 'default' };
    42→}
    43→
    44→/**
    45→ * Parse executor config from database JSON
    46→ * Handles null/undefined and validates the shape
    47→ */
    48→export function parseExecutorConfig(
    49→  executorType: string | null | undefined,
    50→  executorConfig: unknown
    51→): ExecutorConfig | null {
    52→  if (!executorType) {
    53→    return null;
    54→  }
    55→
    56→  if (executorType === 'default') {
    57→    return { type: 'default' };
    58→  }
    59→
    60→  if (executorType === 'custom_url' && executorConfig && typeof executorConfig === 'object') {
    61→    const config = executorConfig as { url?: string; apiKey?: string };
    62→    if (config.url && typeof config.url === 'string') {
    63→      return {
    64→        type: 'custom_url',
    65→        url: config.url,
    66→        apiKey: typeof config.apiKey === 'string' ? config.apiKey : undefined,
    67→      };
    68→    }
    69→  }
    70→
    71→  return null;
    72→}
