    74→/**
    75→ * Execute a tool using a custom URL executor
    76→ */
    77→async function executeWithCustomUrl(
    78→  url: string,
    79→  apiKey: string | undefined,
    80→  request: ExecuteToolRequest,
    81→  timeout: number = DEFAULT_TIMEOUT
    82→): Promise<ExecuteToolResponse> {
    83→  const startTime = Date.now();
    84→
    85→  const headers: Record<string, string> = {
    86→    'Content-Type': 'application/json',
    87→  };
    88→
    89→  if (apiKey) {
    90→    headers.Authorization = `Bearer ${apiKey}`;
    91→  }
    92→
    93→  try {
    94→    const controller = new AbortController();
    95→    const timeoutId = setTimeout(() => controller.abort(), timeout);
    96→
    97→    const response = await fetch(`${url}/execute-tool`, {
    98→      method: 'POST',
    99→      headers,
   100→      body: JSON.stringify(request),
   101→      signal: controller.signal,
   102→    });
   103→
   104→    clearTimeout(timeoutId);
   105→
   106→    const executionTimeMs = Date.now() - startTime;
   107→
   108→    if (!response.ok) {
   109→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
   110→        error?: string;
   111→      };
   112→      return {
   113→        success: false,
   114→        error: errorData.error || `Executor error: ${response.status}`,
   115→        executionTimeMs,
   116→      };
   117→    }
   118→
   119→    const result = (await response.json()) as ExecuteToolResponse;
   120→
   121→    return {
   122→      success: result.success,
   123→      output: result.output,
   124→      error: result.error,
   125→      executionTimeMs: result.executionTimeMs || executionTimeMs,
   126→    };
   127→  } catch (error) {
   128→    const executionTimeMs = Date.now() - startTime;
   129→
   130→    if (error instanceof Error && error.name === 'AbortError') {
   131→      return {
   132→        success: false,
   133→        error: 'Execution timeout',
   134→        executionTimeMs,
   135→      };
   136→    }
   137→
   138→    return {
   139→      success: false,
   140→      error: error instanceof Error ? error.message : String(error),
   141→      executionTimeMs,
   142→    };
   143→  }
   144→}
