   235→/**
   236→ * Test a custom executor by running a simple tool execution
   237→ *
   238→ * @param url - Executor URL to test
   239→ * @param apiKey - Optional API key for authentication
   240→ * @returns Test execution result
   241→ */
   242→export async function testExecutor(
   243→  url: string,
   244→  apiKey?: string
   245→): Promise<{ success: boolean; executionTimeMs: number; error?: string }> {
   246→  const testRequest: ExecuteToolRequest = {
   247→    packageName: '@tpmjs/hello',
   248→    name: 'helloWorldTool',
   249→    version: '0.0.2',
   250→    params: { includeTimestamp: true },
   251→  };
   252→
   253→  const result = await executeWithCustomUrl(url, apiKey, testRequest, 30000); // 30 second timeout for test (includes npm install)
   254→
   255→  return {
   256→    success: result.success,
   257→    executionTimeMs: result.executionTimeMs,
   258→    error: result.error,
   259→  };
   260→}
