   262→/**
   263→ * Verify a custom executor URL is valid and operational
   264→ *
   265→ * @param url - Executor URL to verify
   266→ * @param apiKey - Optional API key for authentication
   267→ * @returns Verification result
   268→ */
   269→export async function verifyExecutor(
   270→  url: string,
   271→  apiKey?: string
   272→): Promise<{
   273→  valid: boolean;
   274→  healthCheck?: { healthy: boolean; response?: ExecutorHealthResponse };
   275→  testExecution?: { success: boolean; executionTimeMs: number };
   276→  errors: string[];
   277→}> {
   278→  const errors: string[] = [];
   279→
   280→  // Validate URL format
   281→  try {
   282→    const parsed = new URL(url);
   283→    if (parsed.protocol !== 'https:' && process.env.NODE_ENV === 'production') {
   284→      errors.push('Custom executor URL must use HTTPS in production');
   285→    }
   286→  } catch {
   287→    errors.push('Invalid URL format');
   288→    return { valid: false, errors };
   289→  }
   290→
   291→  // Check health endpoint
   292→  const healthResult = await checkExecutorHealth(url, apiKey);
   293→  if (!healthResult.healthy) {
   294→    errors.push(healthResult.error || 'Health check failed');
   295→  }
   296→
   297→  // Test execution (only if health check passed)
   298→  let testResult: { success: boolean; executionTimeMs: number } | undefined;
   299→  if (healthResult.healthy) {
   300→    const execResult = await testExecutor(url, apiKey);
   301→    testResult = {
   302→      success: execResult.success,
   303→      executionTimeMs: execResult.executionTimeMs,
   304→    };
   305→    if (!execResult.success) {
   306→      errors.push(execResult.error || 'Test execution failed');
   307→    }
   308→  }
   309→
   310→  return {
   311→    valid: errors.length === 0,
   312→    healthCheck: {
   313→      healthy: healthResult.healthy,
   314→      response: healthResult.response,
   315→    },
   316→    testExecution: testResult,
   317→    errors,
   318→  };
   319→}
