   321→/**
   322→ * Get executor description for display
   323→ */
   324→export function getExecutorDescription(config: ExecutorConfig | null): string {
   325→  if (!config || config.type === 'default') {
   326→    return 'TPMJS Default Executor';
   327→  }
   328→
   329→  if (config.type === 'custom_url') {
   330→    try {
   331→      const url = new URL(config.url);
   332→      return `Custom: ${url.hostname}`;
   333→    } catch {
   334→      return 'Custom Executor';
   335→    }
   336→  }
   337→
   338→  return 'Unknown Executor';
   339→}
