```typescript
import type { Prisma } from '@prisma/client';
import { prisma } from '@tpmjs/db';

export interface TrackExecutionParams {
  eventType: 'tool_call' | 'agent_run' | 'collection_use' | 'scenario_run';
  source: 'mcp_http' | 'mcp_sse' | 'agent_chat' | 'ui_simulation' | 'scenario' | 'omega';
  userId?: string;
  apiKeyId?: string;
  toolId?: string;
  agentId?: string;
  collectionId?: string;
  toolName?: string;
  packageName?: string;
  status: 'success' | 'error' | 'timeout';
  durationMs?: number;
  tokensIn?: number;
  tokensOut?: number;
  errorCode?: string;
  errorMessage?: string;
}

/**
 * Track an execution event (fire-and-forget pattern)
 * Never throws - failures are logged but don't break the main operation.
 * Follows the same pattern as logActivity() in ~/lib/activity.ts
 */
export function trackExecution(params: TrackExecutionParams): void {
  trackExecutionAsync(params).catch((error) => {
    console.error('[Execution Tracking] Error:', error);
  });
}

async function trackExecutionAsync(params: TrackExecutionParams): Promise<void> {
  await prisma.executionEvent.create({
    data: {
      eventType: params.eventType,
      source: params.source,
      userId: params.userId,
      apiKeyId: params.apiKeyId,
      toolId: params.toolId,
      agentId: params.agentId,
      collectionId: params.collectionId,
      toolName: params.toolName,
      packageName: params.packageName,
      status: params.status,
      durationMs: params.durationMs,
      tokensIn: params.tokensIn,
      tokensOut: params.tokensOut,
      errorCode: params.errorCode,
      errorMessage: params.errorMessage?.substring(0, 5000), // Truncate
    },
  });
}
```

This mirrors the exact pattern of `logActivity()` in `/Users/ajaxdavis/repos/tpmjs/tpmjs/apps/web/src/lib/activity.ts` (lines 19-37): fire-and-forget with a `.catch()` that logs but never throws.

